	private static AdjacencyRun runAdjacency(Kernel ir, long[] roots, CountingView view, long ledgerBytes) {
		System.setProperty(KernelOptionalReplay.ENABLED_PROPERTY, "true");
		var manager = LmdbQueryMemoryManager.createForTesting(ledgerBytes, ledgerBytes);
		LmdbNativeKernelInterpreter execution = LmdbNativeKernelInterpreter.forRows(ir, PullRestoreTestMode.VERIFY);
		assertNotNull(execution);
		try (var ledger = manager.openQuery()) {
			try {
				execution.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[] { view },
						new long[] { 0 }, new long[0], new long[][] { roots }).withMemoryLedger(ledger));
				int rows = 0;
				long[] row = new long[ir.stride()];
				while (execution.fill(row, 1) != 0) {
					rows++;
				}
				return new AdjacencyRun(rows, execution.workCounters().optionalArmReplays(),
						execution.workCounters().optionalCacheBypasses());
			} finally {
				execution.close();
			}
		}
	}

	private static final class CountingView implements NativeLmdbQuerySource.NativeAdjacency {
		final long firstKey;
		final long[][] rows;
		int finds;

		CountingView(long firstKey, long[][] rows) {
			this.firstKey = firstKey;
			this.rows = rows;
		}

		@Override
		public long find(long key) {
			finds++;
			long index = key - firstKey;
			return index >= 0 && index < rows.length && rows[(int) index].length != 0 ? index + 1 : NOT_FOUND;
		}

		@Override
		public long size(long handle) {
			return rows[Math.toIntExact(handle) - 1].length;
		}

		@Override
		public long neighborAt(long handle, long offset) {
			return rows[Math.toIntExact(handle) - 1][Math.toIntExact(offset)];
		}

		@Override
		public long contextAt(long handle, long offset) {
			return 0;
		}
	}

	private record Run(List<String> rows, int scanOpens, long armReplays, long bypasses, long peakRetainedBytes) {
	}

	private static Run run(Kernel ir, long[] roots, long[][] quads, boolean replayEnabled, long ledgerBytes) {
		System.setProperty(KernelOptionalReplay.ENABLED_PROPERTY, Boolean.toString(replayEnabled));
		QuadScanner scanner = new QuadScanner(quads);
		var manager = LmdbQueryMemoryManager.createForTesting(ledgerBytes, ledgerBytes);
		LmdbNativeKernelInterpreter execution = LmdbNativeKernelInterpreter.forRows(ir, PullRestoreTestMode.VERIFY);
		assertNotNull(execution);
		try (var ledger = manager.openQuery()) {
			try {
				execution.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0],
						new long[] { P, Q }, new long[0], new long[][] { roots }, null, scanner)
								.withMemoryLedger(ledger));
				List<String> rows = new ArrayList<>();
				long[] row = new long[ir.stride()];
				long peak = 0;
				while (execution.fill(row, 1) != 0) {
					rows.add(Arrays.toString(row));
					peak = Math.max(peak, ledger.usedBytes());
				}
				return new Run(rows, scanner.opens, execution.workCounters().optionalArmReplays(),
						execution.workCounters().optionalCacheBypasses(), peak);
			} finally {
				execution.close();
			}
		}
	}

	private static final class QuadScanner implements KernelScanner {
		final long[][] quads;
		int opens;

		QuadScanner(long[][] quads) {
			this.quads = quads;
		}

		@Override
		public KernelQuadCursor open(int scanId, long s, long p, long o, long c) {
			opens++;
			List<long[]> matches = new ArrayList<>();
			for (long[] quad : quads) {
				if ((s < 0 || quad[0] == s) && (p < 0 || quad[1] == p) && (o < 0 || quad[2] == o)
						&& (c < 0 || quad[3] == c)) {
					matches.add(quad);
				}
			}
			return new KernelQuadCursor() {
				int next;

				@Override
				public int fill(long[] buffer, int maxRows) {
					int count = 0;
					while (count < maxRows && next < matches.size()) {
						System.arraycopy(matches.get(next++), 0, buffer, count++ * 4, 4);
					}
					return count;
				}

				@Override
				public void close() {
				}
			};
		}
	}
